// A dependency array: the effect re-runs only when the dep changed.
const log = [];
let count = 0;
let lastDep = 0;
function updateCount(n) {
  count = n;
  if (n !== lastDep) {
    log.push("fetch");
    lastDep = n;
  }
  log.push("count:" + count);
}
updateCount(1);
updateCount(1);
updateCount(2);
console.log(log.join(","));

