// Cleanup: the effect returns a function that undoes its setup.
let listeners = 0;
function subscribe() {
  listeners = listeners + 1;
  return function () { listeners = listeners - 1; };
}
const unsubscribe = subscribe();
const unsubscribe2 = subscribe();
unsubscribe();
console.log(listeners);

